def resolve(path, cwd, links):
    if not path or not cwd or links is None:
        return None

    if not cwd.startswith('/'):
        return None

    # Normalize cwd: remove trailing slash unless it's root
    if cwd != '/' and cwd.endswith('/'):
        cwd = cwd.rstrip('/')

    # Start with cwd if path is relative, otherwise start with empty
    if path.startswith('/'):
        current = ''
    else:
        current = cwd

    # Split path into components
    components = path.split('/')
    link_count = 0

    i = 0
    while i < len(components):
        comp = components[i]
        i += 1

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            continue

        # Handle '..'
        if comp == '..':
            if current == '/':
                # Stay at root
                pass
            else:
                # Move to parent
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            continue

        # Append component to current path
        if current == '/':
            current = '/' + comp
        else:
            current = current + '/' + comp

        # Check if this path is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current]

            # Resolve remaining components from the target
            if target.startswith('/'):
                # Absolute target
                current = ''
                target_components = target.split('/')
            else:
                # Relative target - relative to the directory containing the link
                if current == '/':
                    current = ''
                else:
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                target_components = target.split('/')

            # Prepend remaining components and target components
            components = target_components + components[i:]
            i = 0

    # Normalize result
    if current == '':
        current = '/'

    # Remove trailing slash unless it's root
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

